package com.rumitx.app;
import android.content.*;import android.database.*;import android.database.sqlite.*;import android.app.*;
/** Durable radio messages. A module acknowledgement is distinct from delivery. */
public final class MessageStore extends SQLiteOpenHelper implements java.lang.AutoCloseable {
 public MessageStore(Context c){super(c,"messages.db",null,2);}
 public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE messages (_id INTEGER PRIMARY KEY AUTOINCREMENT, peer TEXT NOT NULL, body TEXT NOT NULL, direction TEXT NOT NULL, status TEXT NOT NULL, time INTEGER NOT NULL)");createGeoChat(d);}
 public void onUpgrade(SQLiteDatabase d,int old,int next){createGeoChat(d);}
 private void createGeoChat(SQLiteDatabase d){d.execSQL("CREATE TABLE IF NOT EXISTS geochat_seen (uid TEXT PRIMARY KEY, time INTEGER NOT NULL)");}
 public boolean claimGeoChat(String uid){SQLiteDatabase d=getWritableDatabase();d.delete("geochat_seen","time<?",new String[]{""+(System.currentTimeMillis()-86400000L)});ContentValues v=new ContentValues();v.put("uid",uid);v.put("time",System.currentTimeMillis());return d.insertWithOnConflict("geochat_seen",null,v,SQLiteDatabase.CONFLICT_IGNORE)!=-1;}
 public long add(String peer,String body,String direction,String status){ContentValues v=new ContentValues();v.put("peer",peer);v.put("body",body);v.put("direction",direction);v.put("status",status);v.put("time",System.currentTimeMillis());return getWritableDatabase().insertOrThrow("messages",null,v);}
 public void status(long id,String status){ContentValues v=new ContentValues();v.put("status",status);getWritableDatabase().update("messages",v,"_id=?",new String[]{""+id});}
 public java.util.List<String> peers(){java.util.List<String> peers=new java.util.ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT DISTINCT peer FROM messages ORDER BY peer",null)){while(c.moveToNext())peers.add(c.getString(0));}return peers;}
 public String history(){return history(null);}
 public String history(String peer){StringBuilder out=new StringBuilder();try(Cursor c=getReadableDatabase().rawQuery("SELECT peer,body,direction,status,time FROM messages "+(peer==null?"":"WHERE peer=? ")+"ORDER BY _id DESC LIMIT 100",peer==null?null:new String[]{peer})){while(c.moveToNext()){out.append(c.getString(2).equals("in")?"ON ":"TO ").append(c.getString(0)).append(" · ").append(android.text.format.DateFormat.format("MM/dd HH:mm",c.getLong(4))).append('\n').append(c.getString(1)).append('\n').append(c.getString(3)).append("\n\n");}}return out.length()==0?"No messages yet.":out.toString();}
 public static void attach(Context context,RadioController radio){final Context app=context.getApplicationContext();radio.setSmsListener(message->{try(MessageStore store=new MessageStore(app)){store.add(message[0],message[1],"in","Received from radio module · sender ID unverified");}android.content.SharedPreferences unread=app.getSharedPreferences("message_state",0);unread.edit().putInt("unread",unread.getInt("unread",0)+1).apply();com.rumitx.app.tak.GeoChatService.forwardIncoming(message[0],message[1]);NotificationManager manager=(NotificationManager)app.getSystemService(Context.NOTIFICATION_SERVICE);manager.createNotificationChannel(new NotificationChannel("rumitx_messages","Radio messages",NotificationManager.IMPORTANCE_DEFAULT));PendingIntent open=PendingIntent.getActivity(app,240,new Intent(app,com.rumitx.app.tak.MessagingStatusActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);manager.notify(240,new Notification.Builder(app,"rumitx_messages").setSmallIcon(R.drawable.ic_tak_notification).setContentTitle("Radio message on "+message[0]).setContentText(message[1]).setContentIntent(open).setAutoCancel(true).build());});}
}
